import{_ as i,c as l,o as e,ag as t}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/troubleshooting.md","filePath":"ja/guide/troubleshooting.md","lastUpdated":1794112334000}'),s={name:"ja/guide/troubleshooting.md"};function o(r,a,n,h,p,c){return e(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><h2 id="よくある問題" tabindex="-1">よくある問題 <a class="header-anchor" href="#よくある問題" aria-label="Permalink to &quot;よくある問題&quot;">​</a></h2><h3 id="アプリが起動しない" tabindex="-1">アプリが起動しない <a class="header-anchor" href="#アプリが起動しない" aria-label="Permalink to &quot;アプリが起動しない&quot;">​</a></h3><p><strong>症状</strong>：Nicasa の起動に失敗する、またはすぐにクラッシュする</p><p><strong>解決方法</strong>：</p><ol><li>macOS 10.13 以降で実行していることを確認してください</li><li>少なくとも 4GB の RAM があることを確認してください</li><li>Mac を再起動してください</li><li>Mac App Store から Nicasa を再インストールしてください</li><li>競合するアプリケーションがないか確認してください</li></ol><h3 id="スクリーンショットが動作しない" tabindex="-1">スクリーンショットが動作しない <a class="header-anchor" href="#スクリーンショットが動作しない" aria-label="Permalink to &quot;スクリーンショットが動作しない&quot;">​</a></h3><p><strong>症状</strong>：スクリーンショット機能が動作しない</p><p><strong>解決方法</strong>：</p><ol><li><strong>画面収録の権限を付与する</strong>： <ul><li>システム設定 &gt; プライバシーとセキュリティ &gt; 画面収録 に移動します</li><li>Nicasa の横のチェックボックスをオンにします</li><li>Nicasa を再起動します</li></ul></li><li>他のスクリーンショットツールが動作していないことを確認してください</li><li>Mac を再起動してみてください</li></ol><h3 id="chrome-拡張機能が動作しない" tabindex="-1">Chrome 拡張機能が動作しない <a class="header-anchor" href="#chrome-拡張機能が動作しない" aria-label="Permalink to &quot;Chrome 拡張機能が動作しない&quot;">​</a></h3><p><strong>症状</strong>：拡張機能が表示されない、または画像を抽出しない</p><p><strong>解決方法</strong>：</p><ol><li>Chrome で拡張機能が有効になっていることを確認してください</li><li>互換性のあるバージョンの Chrome を使用しているか確認してください</li><li>ウェブページを再読み込みしてみてください</li><li>拡張機能を再インストールしてください</li><li>ブラウザのキャッシュと Cookie をクリアしてください</li></ol><h3 id="画像が読み込まれない" tabindex="-1">画像が読み込まれない <a class="header-anchor" href="#画像が読み込まれない" aria-label="Permalink to &quot;画像が読み込まれない&quot;">​</a></h3><p><strong>症状</strong>：サムネイルが表示されない、または画像が開かない</p><p><strong>解決方法</strong>：</p><ol><li>画像ファイルのアクセス権を確認してください</li><li>画像が破損していないことを確認してください</li><li>対応形式（JPEG、PNG、GIF、BMP、TIFF、WebP）であることを確認してください</li><li>フォルダをもう一度開いてみてください</li><li>Nicasa を再起動してください</li></ol><h3 id="動作が遅い" tabindex="-1">動作が遅い <a class="header-anchor" href="#動作が遅い" aria-label="Permalink to &quot;動作が遅い&quot;">​</a></h3><p><strong>症状</strong>：アプリの反応が鈍い、またはサムネイルの読み込みが遅い</p><p><strong>解決方法</strong>：</p><ol><li>メモリを多く使う他のアプリを閉じてください</li><li>十分な空きメモリを確保してください（8GB 推奨）</li><li>環境設定でサムネイルのグリッドサイズを小さくしてください</li><li>アプリのキャッシュをクリアしてください</li><li>Mac を再起動してください</li></ol><h3 id="ai-エディターが動作しない" tabindex="-1">AI エディターが動作しない <a class="header-anchor" href="#ai-エディターが動作しない" aria-label="Permalink to &quot;AI エディターが動作しない&quot;">​</a></h3><p><strong>症状</strong>：AI 編集ツールが利用できない、または機能しない</p><p><strong>解決方法</strong>：</p><ol><li>安定したインターネット接続を確認してください（一部の機能で必要です）</li><li>Mac が最低要件を満たしているか確認してください</li><li>Nicasa を再起動してください</li><li>最新バージョンに更新してください</li><li>問題が続く場合はサポートにお問い合わせください</li></ol><h3 id="権限の問題" tabindex="-1">権限の問題 <a class="header-anchor" href="#権限の問題" aria-label="Permalink to &quot;権限の問題&quot;">​</a></h3><p><strong>症状</strong>：アプリが権限を要求する、または一部の機能が動作しない</p><p><strong>解決方法</strong>：</p><ol><li><strong>画面収録</strong>：システム設定 &gt; プライバシーとセキュリティ &gt; 画面収録</li><li><strong>アクセシビリティ</strong>：システム設定 &gt; プライバシーとセキュリティ &gt; アクセシビリティ（オーバーレイモード用）</li><li><strong>ファイルとフォルダ</strong>：システム設定 &gt; プライバシーとセキュリティ &gt; ファイルとフォルダ</li><li>権限を付与した後に Nicasa を再起動してください</li></ol><h3 id="オーバーレイモードの問題" tabindex="-1">オーバーレイモードの問題 <a class="header-anchor" href="#オーバーレイモードの問題" aria-label="Permalink to &quot;オーバーレイモードの問題&quot;">​</a></h3><p><strong>症状</strong>：透明オーバーレイモードが正しく動作しない</p><p><strong>解決方法</strong>：</p><ol><li>システム設定でアクセシビリティの権限を付与してください</li><li>他のオーバーレイ系ツールが動作していないことを確認してください</li><li>オーバーレイモードをオフにしてから再度オンにしてみてください</li><li>Nicasa を再起動してください</li></ol><h2 id="エラーメッセージ" tabindex="-1">エラーメッセージ <a class="header-anchor" href="#エラーメッセージ" aria-label="Permalink to &quot;エラーメッセージ&quot;">​</a></h2><h3 id="「画面収録の権限が必要です」" tabindex="-1">「画面収録の権限が必要です」 <a class="header-anchor" href="#「画面収録の権限が必要です」" aria-label="Permalink to &quot;「画面収録の権限が必要です」&quot;">​</a></h3><p><strong>解決方法</strong>：上記の「スクリーンショットが動作しない」セクションの手順で画面収録の権限を付与してください。</p><h3 id="「画像を読み込めませんでした」" tabindex="-1">「画像を読み込めませんでした」 <a class="header-anchor" href="#「画像を読み込めませんでした」" aria-label="Permalink to &quot;「画像を読み込めませんでした」&quot;">​</a></h3><p><strong>考えられる原因</strong>：</p><ul><li>ファイルが破損している</li><li>対応していない形式</li><li>ファイルのアクセス権の問題</li><li>ファイルが大きすぎる</li></ul><p><strong>解決方法</strong>：</p><ol><li>「プレビュー」アプリでファイルを開き、有効かどうか確認してください</li><li>対応形式に変換してください</li><li>ファイルのアクセス権を確認してください</li><li>ファイルサイズが妥当か確認してください</li></ol><h3 id="「拡張機能が応答しません」" tabindex="-1">「拡張機能が応答しません」 <a class="header-anchor" href="#「拡張機能が応答しません」" aria-label="Permalink to &quot;「拡張機能が応答しません」&quot;">​</a></h3><p><strong>解決方法</strong>：ウェブページを再読み込みして再試行してください。繰り返し発生する場合は、拡張機能を再インストールしてください。</p><h2 id="サポートを受ける" tabindex="-1">サポートを受ける <a class="header-anchor" href="#サポートを受ける" aria-label="Permalink to &quot;サポートを受ける&quot;">​</a></h2><p>問題が解決しない場合：</p><ol><li>このトラブルシューティングガイドを確認してください</li><li><a href="/ja/guide/faq.html">よくある質問</a>をご覧ください</li><li><a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub</a> で issue を報告してください</li><li>macOS のバージョン、Nicasa のバージョン、問題を再現する詳細な手順を記載してください</li></ol><h2 id="システム情報" tabindex="-1">システム情報 <a class="header-anchor" href="#システム情報" aria-label="Permalink to &quot;システム情報&quot;">​</a></h2><p>問題を報告する際は、以下を含めてください：</p><ul><li>macOS のバージョン（Apple メニュー &gt; この Mac について）</li><li>Nicasa のバージョン（Nicasa &gt; Nicasa について）</li><li>Mac のモデルとチップ（Apple シリコンまたは Intel）</li><li>問題を再現する手順</li><li>表示されたエラーメッセージ</li></ul><p>これは通常、画像ファイルが移動または削除されたことを意味します。フォルダを再度開くか、別のディレクトリを選択してみてください。</p><h3 id="「対応していない形式です」" tabindex="-1">「対応していない形式です」 <a class="header-anchor" href="#「対応していない形式です」" aria-label="Permalink to &quot;「対応していない形式です」&quot;">​</a></h3><p>画像形式が認識されません。<a href="/ja/guide/usage.html">対応形式</a>の一覧を確認するか、互換性のある形式に変換してください。</p><h3 id="「メモリが不足しています」" tabindex="-1">「メモリが不足しています」 <a class="header-anchor" href="#「メモリが不足しています」" aria-label="Permalink to &quot;「メモリが不足しています」&quot;">​</a></h3><p>システムの RAM が不足しています。他のアプリを閉じるか、メモリを増設してください。</p><h2 id="高度なトラブルシューティング" tabindex="-1">高度なトラブルシューティング <a class="header-anchor" href="#高度なトラブルシューティング" aria-label="Permalink to &quot;高度なトラブルシューティング&quot;">​</a></h2><h3 id="ログの表示" tabindex="-1">ログの表示 <a class="header-anchor" href="#ログの表示" aria-label="Permalink to &quot;ログの表示&quot;">​</a></h3><p>アプリのログにアクセスするには：</p><ol><li>ヘルプ &gt; ログを表示 に移動します</li><li>または次の場所でログを確認できます： <ul><li>Windows：<code>%APPDATA%\\Nicasa\\logs</code></li><li>macOS：<code>~/Library/Application Support/Nicasa/logs</code></li><li>Linux：<code>~/.config/Nicasa/logs</code></li></ul></li></ol><h3 id="アプリのリセット" tabindex="-1">アプリのリセット <a class="header-anchor" href="#アプリのリセット" aria-label="Permalink to &quot;アプリのリセット&quot;">​</a></h3><p>すべての設定を既定値に戻すには：</p><ol><li>Nicasa を終了します</li><li>アプリのデータフォルダを削除します</li><li>Nicasa を再起動します</li></ol><h3 id="コマンドラインオプション" tabindex="-1">コマンドラインオプション <a class="header-anchor" href="#コマンドラインオプション" aria-label="Permalink to &quot;コマンドラインオプション&quot;">​</a></h3><p>上級者向けに、Nicasa はコマンドライン引数に対応しています：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 詳細ログを有効にする</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-settings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # すべての設定をリセットする</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 指定したフォルダを開く</span></span></code></pre></div><h2 id="さらにサポートが必要な場合" tabindex="-1">さらにサポートが必要な場合 <a class="header-anchor" href="#さらにサポートが必要な場合" aria-label="Permalink to &quot;さらにサポートが必要な場合&quot;">​</a></h2><p>これらの解決方法で問題が解決しない場合：</p><ol><li><a href="/ja/guide/faq.html">よくある質問</a>をご覧ください</li><li>既存の <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">issues</a> を検索してください</li><li>新しい issue を作成し、以下を記載してください： <ul><li>オペレーティングシステムとバージョン</li><li>Nicasa のバージョン</li><li>問題を再現する手順</li><li>エラーメッセージやスクリーンショット</li></ul></li></ol>`,68)])])}const u=i(s,[["render",o]]);export{g as __pageData,u as default};
